using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Quotations.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.Quotations.Commands.CancelQuotation;public sealed class CancelQuotationCommandHandler(IQuotationRepository repository,IApplicationDbContext db):IRequestHandler<CancelQuotationCommand,Result<QuotationDto>>{public async Task<Result<QuotationDto>>Handle(CancelQuotationCommand request,CancellationToken cancellationToken){var e=await repository.FindForUpdateAsync(request.Id,cancellationToken);if(e is null)return Result.Failure<QuotationDto>(QuotationErrors.NotFound);if(e.Status.ToString() is not ("Draft" or "Sent"))return Result.Failure<QuotationDto>(QuotationErrors.NotDraft);e.Cancel();await db.SaveChangesAsync(cancellationToken);return Result.Success(QuotationDto.FromEntity(e));}}
